function updateUI(){drawMinimap();let p=battle.player,b=battle.bases[battle.localTeam??0];$('hp').innerHTML=Math.ceil(p.hp)+'<span> / '+p.maxHp+'</span>';$('hpfill').style.width=(p.hp/p.maxHp*100)+'%';$('weapon').textContent=p.tank?'坦克裝甲':'裝備 Lv.'+(p.gear+1);$('carry').textContent=p.carrying?'▣ 搬運中':p.hp<=0?(b.hp>0?'重生 '+Math.ceil(battle.respawn)+' 秒':'觀戰中'):'空手';$('squad').textContent='隊伍 '+battle.alive(battle.localTeam??0).length+' / 6';$('timer').textContent=formatTime(battle.limit-battle.time);$('stock').textContent=b.store+' 箱';let home=b.hp>0&&p.hp>0&&dist(p,b)<8;$('buildpanel').style.opacity=home?1:.76;for(let button of document.querySelectorAll('[data-craft]')){let kind=button.dataset.craft;button.disabled=!home||b.store<RECIPES[kind]||(kind==='weapon'&&p.gear>=2)||(kind==='tank'&&p.tank)||(kind==='buddy'&&battle.alive(battle.localTeam??0).length>=6);}$('buildhint').textContent=home?'站在基地內，可立即合成。':'返回藍隊基地才可合成。';$('interactText').textContent=p.carrying?(dist(p,b)<7?'交付箱子':'放下箱子'):'拾起箱子';$('commandText').textContent=battle.mode==='follow'?'隊友跟隨':'隊友出擊';$('objectiveText').textContent=battle.time<battle.protection?'新手保護 '+Math.ceil(battle.protection-battle.time)+' 秒 · 先搬箱回基地，再合成隊伍。':p.carrying?'搬回藍隊基地，按搬箱鍵交付。':p.tank?'坦克就緒 · 守住基地，擊敗其餘三隊！':'搶空投 → 搬回基地 → 合成隊伍 → 擊敗敵方隊伍';for(let base of battle.bases){let card=$('team'+base.team);card.classList.toggle('dead',base.hp<=0);card.querySelector('i').style.width=(base.hp/base.maxHp*100)+'%';card.querySelector('span').textContent=base.hp<=0?(battle.alive(base.team).length?'失基地':'出局'):Math.ceil(base.hp);}updateBuildHUD(battle);}
function formatTime(s){s=Math.max(0,Math.ceil(s));return Math.floor(s/60).toString().padStart(2,'0')+':'+(s%60).toString().padStart(2,'0');}
function updateCamera(dt){let p=battle?.player,playing=battle?.status!=='ready'&&!overview;if(playing&&p){let wanted=new THREE.Vector3(p.x,terrainHeight(p.x,p.y),-p.y);target.lerp(wanted,1-Math.exp(-dt*5));}else target.lerp(new THREE.Vector3(0,0,0),1-Math.exp(-dt*2));let wantedZoom=playing?zoom*(innerWidth<600?1.5:1):175;objects.camSpan=THREE.MathUtils.lerp(objects.camSpan||108,wantedZoom,1-Math.exp(-dt*3));let aspect=innerWidth/innerHeight,span=objects.camSpan;camera.left=-span*aspect/2;camera.right=span*aspect/2;camera.top=span/2;camera.bottom=-span/2;camera.updateProjectionMatrix();camera.position.copy(target).add(cameraOffset);camera.lookAt(target);
 if(p&&playing){for(let b of buildings){let dx=b.x-p.x,dy=b.y-p.y,forward=dx*.588-dy*.809,across=Math.abs(dx*.809+dy*.588);let fade=forward>0&&forward<55&&across<b.width/2+3&&b.height>5;if(fade!==b.fade){b.fade=fade;for(let m of b.materials){m.transparent=fade;m.opacity=fade?.20:1;m.depthWrite=!fade;m.needsUpdate=true;}}}}
}
